-- Verifies SQL generated by scripts/foods (applied by scripts/db-test.sh before this file).
\set dave '44444444-4444-4444-4444-444444444444'
insert into auth.users (id, email) values (:'dave', 'dave@example.com');
set role authenticated;
select set_config('request.jwt.claim.sub', :'dave', false);
do $$
declare r record;
begin
  -- re-import of v2 keeps ids stable and deactivates foods missing from the new edition
  select * into r from public.search_foods('ふぃくすちゃ穀物') limit 1;
  if r.id is null then raise exception 'FAIL: imported food not searchable'; end if;
  if r.source_version <> 'fixture-v2' then raise exception 'FAIL: not updated to v2 (%)', r.source_version; end if;
  if r.fat_g <> 0.3 or (r.value_flags->>'fat_g') <> 'estimated' then raise exception 'FAIL: flags'; end if;
  if (select count(*) from public.search_foods('ふぃくすちゃ卵')) <> 1 then raise exception 'FAIL: egg'; end if;
  if (select carbohydrate_g from public.search_foods('ふぃくすちゃ卵')) is not null then
    raise exception 'FAIL: missing value must be NULL';
  end if;
  if (select count(*) from public.food_master where name like 'フィクスチャ%') <> 2 then
    raise exception 'FAIL: duplicate rows after re-import';
  end if;
end $$;
reset role;
\echo 'FOOD IMPORT TESTS PASSED'
